  @protected
  void sse_encode_play_context_dto(
    PlayContextDto self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case PlayContextDto_Library(sort: final sort):
        sse_encode_i_32(0, serializer);
        sse_encode_track_sort_dto(sort, serializer);
      case PlayContextDto_Album(albumId: final albumId):
        sse_encode_i_32(1, serializer);
        sse_encode_i_64(albumId, serializer);
      case PlayContextDto_Artist(artistId: final artistId):
        sse_encode_i_32(2, serializer);
        sse_encode_i_64(artistId, serializer);
      case PlayContextDto_Genre(name: final name):
        sse_encode_i_32(3, serializer);
        sse_encode_String(name, serializer);
      case PlayContextDto_Playlist(playlistId: final playlistId):
        sse_encode_i_32(4, serializer);
        sse_encode_i_64(playlistId, serializer);
      case PlayContextDto_Loved():
        sse_encode_i_32(5, serializer);
      case PlayContextDto_Folder(sourceId: final sourceId, path: final path):
        sse_encode_i_32(6, serializer);
        sse_encode_i_64(sourceId, serializer);
        sse_encode_String(path, serializer);
    }
  }

